import { useState, useEffect } from "react";

const Memos = ({ state }) => {
  const [memos, setMemos] = useState([]);
  const { contract } = state;

  useEffect(() => {
    const memosMessage = async () => {
      try {
        const memosData = await contract.getMemos();
        setMemos(memosData);
      } catch (error) {
        console.error("Error fetching memos:", error);
      }
    };
    contract && memosMessage();
  }, [contract]);

  return (
    <>
      <p style={{ textAlign: "center", marginTop: "20px" }}>Messages</p>
      {memos.length > 0 ? (
        memos.map((memo, index) => {
          const timestamp = typeof memo.timestamp === "bigint" 
            ? Number(memo.timestamp) 
            : memo.timestamp;
          
          return (
            <div
              className="container-fluid"
              style={{ width: "100%" }}
              key={`${index}-${memo.from}`}
            >
              <table
                style={{
                  marginBottom: "10px",
                }}
              >
                <tbody>
                  <tr>
                    <td
                      style={{
                        backgroundColor: "#96D4D4",
                        border: "1px solid white",
                        borderCollapse: "collapse",
                        padding: "7px",
                        width: "100px",
                      }}
                    >
                      {memo.name}
                    </td>
                    <td
                      style={{
                        backgroundColor: "#96D4D4",
                        border: "1px solid white",
                        borderCollapse: "collapse",
                        padding: "7px",
                        width: "800px",
                      }}
                    >
                      {new Date(timestamp * 1000).toLocaleString()}
                    </td>
                    <td
                      style={{
                        backgroundColor: "#96D4D4",
                        border: "1px solid white",
                        borderCollapse: "collapse",
                        padding: "7px",
                        width: "300px",
                      }}
                    >
                      {memo.message}
                    </td>
                    <td
                      style={{
                        backgroundColor: "#96D4D4",
                        border: "1px solid white",
                        borderCollapse: "collapse",
                        padding: "7px",
                        width: "400px",
                      }}
                    >
                      {memo.from}
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          );
        })
      ) : (
        <p style={{ textAlign: "center", marginTop: "10px" }}>No messages yet</p>
      )}
    </>
  );
};

export default Memos;
